import{appendFileSync}from'node:fs'
const log=(kind,fields={})=>appendFileSync(process.env.DATE_NOW_TRACE,JSON.stringify({realm:'config',kind,...fields})+'\n')
const now=new Date(1700000000123);
const fakeTimers={toFake:['Date','setTimeout','clearTimeout']};
let reads=0;Object.defineProperty(fakeTimers,'now',{enumerable:true,get(){log('now-getter',{receiver:this===fakeTimers,read:++reads});return new Date(1700000000123+reads)}});
export default{test:{include:['clock.test.js','clock.test.mjs'],fileParallelism:false,maxWorkers:1,cache:false,testTimeout:5000,hookTimeout:5000,fakeTimers}}

bodies.clock.test.js:
import{test,vi}from'vitest'
import{appendFileSync}from'node:fs'
const file="js"
test('project clock '+file,()=>{
 const row={realm:'body',kind:'clock',file,clockError:null};
 try{vi.useFakeTimers();row.initial=Date.now();row.date=new Date().getTime();let timer=null;setTimeout(()=>{timer=Date.now()},25);vi.advanceTimersByTime(25);row.after=Date.now();row.timer=timer;row.mocked=vi.getMockedSystemTime()?.getTime()??null;vi.useRealTimers();row.restored=!vi.isFakeTimers();vi.useFakeTimers();row.reinstalled=Date.now()}catch(error){row.clockError={name:error?.name??null,message:error?.message??String(error)}}finally{vi.useRealTimers();row.finallyRestored=!vi.isFakeTimers();appendFileSync(process.env.DATE_NOW_TRACE,JSON.stringify(row)+'\n')}
})

